import { describe, expect, it } from "vitest";

import { locationsIn } from "../src/lib/locations";
import { OUTLINE_PATH, VIEW_HEIGHT, VIEW_WIDTH, project } from "../src/lib/map-au";

/**
 * The outline and the projection are generated by scripts/build_map.py, so
 * these tests guard the generator's output rather than hand-written code. A
 * flipped sign or a swapped axis would still produce a plausible-looking blob,
 * so the assertions are about geography, not shape.
 */
describe("the Australia map", () => {
  it("has an outline with a mainland and Tasmania", () => {
    const subpaths = OUTLINE_PATH.split("Z").filter((p) => p.trim().length > 0);
    expect(subpaths.length).toBe(2);
    expect(OUTLINE_PATH.length).toBeLessThan(4000); // stays inside the page budget
  });

  it("places every station inside the viewBox", () => {
    for (const city of locationsIn("au")) {
      const { x, y } = project(city.lat, city.lon);
      expect(x, city.id).toBeGreaterThanOrEqual(0);
      expect(x, city.id).toBeLessThanOrEqual(VIEW_WIDTH);
      expect(y, city.id).toBeGreaterThanOrEqual(0);
      expect(y, city.id).toBeLessThanOrEqual(VIEW_HEIGHT);
    }
  });

  it("gets the compass right", () => {
    const at = (slug: string) => {
      const city = locationsIn("au").find((l) => l.slug === slug)!;
      return project(city.lat, city.lon);
    };
    // Perth is far west of Sydney.
    expect(at("perth").x).toBeLessThan(at("sydney").x);
    // Darwin is far north of Hobart, and north is up.
    expect(at("darwin").y).toBeLessThan(at("hobart").y);
    // Hobart is south of Melbourne, which is south of Brisbane.
    expect(at("hobart").y).toBeGreaterThan(at("melbourne").y);
    expect(at("melbourne").y).toBeGreaterThan(at("brisbane").y);
    // Brisbane is east of Adelaide.
    expect(at("brisbane").x).toBeGreaterThan(at("adelaide").x);
  });

  it("keeps the aspect ratio plausible for Australia", () => {
    // Australia is wider than it is tall, but not absurdly so.
    const ratio = VIEW_WIDTH / VIEW_HEIGHT;
    expect(ratio).toBeGreaterThan(1.0);
    expect(ratio).toBeLessThan(1.6);
  });
});
